import {readEnemyEffectRows,normalizeBattleEnemies} from './multi-battle-ui.js';
import * as E from './engine.js';
import {captureCombatDisplay} from './combat-display-bridge.js';
import {createCombatDisplayQueue} from './combat-display-queue.js';
import {icon} from './icons.js';
import {SKILL_TREE_DESCRIPTIONS} from './skill-tree-descriptions.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=Object.fromEntries(E.SKILL_TREE_DEFINITION.nodes.map(n=>[n.id,n.name]));
export const DISPLAY_COLORS={physical:'#fff0d0',fire:'#ff9b54',earth:'#d3b77f',water:'#74c9ef',wind:'#a6e1be',light:'#fff5a9',dark:'#bf9cfa',poison:'#bded65',heal:'#8eed9a',shield:'#8bd8f3'};
export function createBattleSliceModel({now=Date.now(),state=null,scenario='fire',seed=scenario==='poison'?13:24}={}){let rng=seed>>>0;const run=(fn,at=now)=>{const random=Math.random,clock=Date.now;Math.random=()=>{rng=(Math.imul(rng,1664525)+1013904223)>>>0;return rng/4294967296;};Date.now=()=>at;try{return fn();}finally{Math.random=random;Date.now=clock;}};
 const s=state?structuredClone(state):run(()=>E.fresh());if(!state){const afterFreshRng=rng;let weapon=s.inventory.find(it=>it.id===s.equip.weapon);for(let attempt=0;weapon.weaponType!=='axe'&&attempt<64;attempt++)weapon=run(()=>E.item('weapon',1,null,0));if(weapon.weaponType!=='axe')throw Error('隔离斧模板未就绪');const oldWeapon=s.equip.weapon;s.inventory=s.inventory.filter(it=>it.id!==oldWeapon);s.inventory.push(weapon);s.equip.weapon=weapon.id;rng=afterFreshRng;s.level=20;const p=s.skillTree.presets[0];p.unlocked=['fracture_strike','ember_brand','iron_vigil','forge_breath','mountain_vitality','forged_resilience'];p.active=['iron_vigil','ember_brand','fracture_strike','forge_breath'];p.passive=['mountain_vitality','forged_resilience'];p.conditions=['always','always','always','low'];s.potionStacks={'healing|0':3};E.equipPotion(s,'healing|0');E.normalizeHealth(s,now);s.heroHp=E.stats(s).hp*.35;if(scenario==='poison'){s.level=30;p.unlocked=['fracture_strike','ember_brand','scatter_ash','iron_vigil','mountain_vitality','forged_resilience'];p.active=['scatter_ash','ember_brand','fracture_strike','iron_vigil'];p.conditions=['always','always','always','always'];}}
 const encounter=s.activeEncounter&&!s.activeEncounter.done?s.activeEncounter:run(()=>E.startInstanceEncounter(s,'dwarf.a01.field',now));if(!encounter)throw Error('无法建立隔离战斗');E.setMultiPaused(s,true,now);const queue=createCombatDisplayQueue();queue.beginBattle(encounter.id);let logs=[],emissionError=null;
 const publish=events=>{const result=queue.emitBatch(events);if(!result.ok)emissionError=result.reason;};
 return {fixture:{seed,initialClock:now,scenario,injuredStart:!state,description:'固定种子的真实A01遭遇；隔离角色初始35%生命演示恢复，非正常新档/产率'},get state(){return s;},get encounter(){return encounter;},get logs(){return [...logs];},get emissionError(){return emissionError;},toggle(at){if(encounter.done)return false;return E.setMultiPaused(s,!!s.running,at);},advance(at){if(!s.running||encounter.done)return [];const batch=captureCombatDisplay(encounter,()=>run(()=>E.step(s,encounter,at),at));logs=[...batch.result,...logs].slice(0,30);publish(batch.events);if(encounter.done)s.running=false;return queue.consume();},select(id){return E.setCombatTarget(s,id);},drink(at){const batch=captureCombatDisplay(encounter,()=>run(()=>E.drinkPotion(s,undefined,at,encounter),at));publish(batch.events);return {used:batch.result,events:queue.consume()};},dispose(){queue.resetSession();}};
}
export function displayTokens(event){if(event.kind==='cast')return [];if(event.outcome==='miss')return [{text:'闪避',color:'#b7bec5',crit:false}];const tokens=[];if(event.hpDelta<0)tokens.push({text:'−'+Math.round(-event.hpDelta),color:DISPLAY_COLORS[event.kind==='poison'?'poison':event.element]??DISPLAY_COLORS.physical,crit:event.crit,tag:event.crit?'暴击':''});if(event.hpDelta>0)tokens.push({text:'+'+Math.round(event.hpDelta),color:DISPLAY_COLORS.heal,crit:false});if(event.shieldDelta!==0)tokens.push({text:(event.shieldDelta>0?'+':'−')+Math.round(Math.abs(event.shieldDelta)),color:DISPLAY_COLORS.shield,crit:false,tag:'盾'});return tokens;}
export function slicePositions(e){const enemies=e.enemies??[],xs=enemies.length===1?[350]:enemies.length===2?[315,405]:[280,355,425];return Object.fromEntries([['hero',{x:110,y:203,sprite:'dwarf'}],...enemies.map((u,i)=>[u.id,{x:xs[i]??425,y:203,sprite:i%2?'golem':'lizard'}])]);}
function skillButtons(s,e){const p=s.skillTree.presets[s.skillTree.selectedPreset];return [...p.active.map((id,i)=>({id,index:i,passive:false})),...p.passive.map((id,i)=>({id,index:i,passive:true}))].map(({id,index,passive})=>`<button class="sliceSkill ${passive?'passive':''}" data-slice-skill="${esc(id||'')}" title="${esc(names[id]||'空槽')}">${icon(!id?'bag':passive?'shield':id.includes('ember')?'fire':id.includes('vigil')?'shield':id.includes('breath')?'herb':'sword')}<span>${esc(names[id]||'空槽')}</span>${!passive&&(e.treeSkillCooldowns?.[id]??e.cd?.[id]??0)>0?`<b class="sliceCd">${Math.ceil(e.treeSkillCooldowns?.[id]??e.cd?.[id]??0)+'回'}</b>`:''}</button>`).join('');}
export function renderSliceShell(model){return `<div class="sliceShell"><header class="sliceHeader"><h1>黑炉 · 山道交锋</h1><small>战斗画面试作 · 隔离角色<br>不读取或写入正式存档</small></header><section class="sliceStage"><canvas id="sliceCanvas" width="480" height="270" aria-label="原创像素战斗场景"></canvas><div id="sliceUnits"></div><div class="sliceFloats" id="sliceFloats"></div><div class="sliceStatus" id="sliceStatus">已暂停</div></section><section class="sliceHud"><div class="sliceSkills" id="sliceSkills">${skillButtons(model.state,model.encounter)}</div><div class="sliceActions"><button class="primary" data-slice-action="toggle">${icon('sword')}<span id="sliceRunLabel">开始</span></button><button data-slice-action="potion">${icon('potionHeal')}<span id="slicePotionCount">药剂</span></button><button data-slice-action="restart">${icon('forge')}<span>重开</span></button><button data-slice-action="log">${icon('book')}<span>战报</span></button><button data-slice-action="record" title="录制场景与飘字，不含外围HUD">${icon('book')}<span>录制场景</span></button></div></section><div class="sliceFooter"><span>Lv.${model.state.level} 受伤试作 · 种子${model.fixture.seed}三敌 · 外观替身</span><span id="sliceOutcome">点击敌人切换目标 · 固定随机种子试作</span></div><div class="sliceHelp" id="sliceHelp" hidden></div><div class="sliceLog" id="sliceLog" hidden></div></div>`;}
export function createBattleSlicePresentation(positions){const animations=new Map(),floats=[],pending=[],seenAnimation=new Set(),lanes=new Map();return {animations,floats,enqueue(events,at){const groups=new Map();for(const event of events){const key=event.castId+'|'+event.sourceId;if(!groups.has(key))groups.set(key,groups.size);const groupOffset=Math.min(650,groups.get(key)*100),hasDamage=events.some(x=>x.castId===event.castId&&x.sourceId===event.sourceId&&['hit','counter','legend'].includes(x.kind));pending.push({event:{...event,animateCast:hasDamage,actionElement:events.find(x=>x.castId===event.castId&&x.sourceId===event.sourceId&&['hit','counter','legend'].includes(x.kind))?.element??event.element},at:at+groupOffset+(event.displayDelayMs??event.segmentIndex*70)+(event.kind==='cast'?0:240)});}},advance(time){pending.sort((a,b)=>a.at-b.at);while(pending.length&&pending[0].at<=time){const {event,at}=pending.shift(),target=positions[event.targetId],source=positions[event.sourceId];if(!target)continue;const key=event.castId+event.sourceId;if(source&&(['hit','counter','legend'].includes(event.kind)||event.kind==='cast'&&event.animateCast)&&!seenAnimation.has(key)){seenAnimation.add(key);animations.set(event.sourceId,{kind:'attack',at,targetId:event.targetId,targetX:target.x,originX:source.x,element:event.actionElement??event.element});}if(event.hpDelta<0||event.shieldDelta<0)animations.set(event.targetId,{kind:'hurt',at});const lane=lanes.get(event.targetId)??0;lanes.set(event.targetId,lane+1);displayTokens(event).forEach((token,i)=>floats.push({...token,x:target.x+(lane%2?9:-9),y:target.y-94-(lane%3)*15-i*15,at}));}for(let i=floats.length-1;i>=0;i--)if(time-floats[i].at>1100)floats.splice(i,1);},clear(){animations.clear();floats.length=0;pending.length=0;seenAnimation.clear();lanes.clear();}};}
export function presentationActorX(position,animation,time){if(animation?.kind!=='attack'||animation.element!=='physical'||!Number.isFinite(animation.targetX))return position.x;const elapsed=time-animation.at;if(elapsed<0||elapsed>=600)return position.x;const direction=Math.sign(animation.targetX-position.x)||1,contact=animation.targetX-direction*40;const progress=elapsed<180?elapsed/180:elapsed<340?1:1-(elapsed-340)/260;return position.x+(contact-position.x)*Math.max(0,Math.min(1,progress));}
export function drawBattleSliceCanvas(canvas,{manifest,images,encounter,positions=slicePositions(encounter),animations=new Map(),time=0,reduced=false,floats=[]}){const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,480,270);for(const bg of manifest.backgrounds)c.drawImage(images.get(bg.file),0,0);for(const [id,p]of Object.entries(positions)){const sprite=manifest.sprites[p.sprite],anim=animations.get(id),mode=!reduced&&anim&&time-anim.at<600?anim.kind:'idle',frames=sprite.animations[mode]??sprite.animations.idle;const index=mode==='idle'?Math.floor(time/500)%frames.length:Math.max(0,Math.min(frames.length-1,Math.floor((time-anim.at)/110)));const f=sprite.frames.find(f=>f.id===frames[index]);c.save();if(encounter.enemies.find(u=>u.id===id)?.hp<=0)c.globalAlpha=.35;c.drawImage(images.get(f.file),(reduced?p.x:presentationActorX(p,anim,time))-sprite.anchor[0],p.y-sprite.anchor[1]);c.restore();}for(const [id,anim]of animations){if(anim.kind!=='attack'||!anim.element||anim.element==='physical')continue;const age=time-anim.at;if(age<60||age>390)continue;const source=positions[id],target=positions[anim.targetId];if(!source||!target)continue;const progress=Math.min(1,Math.max(0,(age-60)/200)),x=source.x+(target.x-source.x)*progress,y=source.y-65+Math.sin(progress*Math.PI)*-12;c.save();const color=DISPLAY_COLORS[anim.element]??'#ff9b54';c.fillStyle=color;if(progress<1){for(let i=0;i<5;i++){c.globalAlpha=1-i*.17;c.fillRect(Math.round(x-i*5*Math.sign(target.x-source.x)),Math.round(y-3+i%2),7-i,6-i*.5);}}else{c.globalAlpha=Math.max(0,1-(age-260)/130);for(let i=0;i<8;i++){const angle=i*Math.PI/4,r=5+(age-260)/10;c.fillRect(Math.round(target.x+Math.cos(angle)*r),Math.round(target.y-65+Math.sin(angle)*r),4,4);}}c.restore();}for(const f of floats){const age=time-f.at;if(age<0||age>1100)continue;c.save();c.globalAlpha=Math.min(1,(1100-age)/300);c.font=`bold ${f.crit?17:13}px monospace`;c.textAlign='center';c.lineWidth=3;const text=f.text+(f.tag?' '+f.tag:''),y=f.y-(reduced?0:age/30);c.strokeStyle='#12151b';c.strokeText(text,f.x,y);c.fillStyle=f.color;c.fillText(text,f.x,y);c.restore();}}
export async function mountBattleSlice(host,{assetRoot='./battle-assets/',scenario='fire'}={}){
 const response=await fetch(assetRoot+'manifest.json');if(!response.ok)throw Error('素材清单未就绪');const manifest=await response.json(),images=new Map();await Promise.all([...manifest.backgrounds,...Object.values(manifest.sprites).flatMap(s=>s.frames)].map(async f=>{const img=new Image();img.src=assetRoot+f.file;await img.decode();images.set(f.file,img);}));
 let model=createBattleSliceModel({scenario}),disposed=false,lastStep=0,raf=0,recorder=null;let position=slicePositions(model.encounter),presentation=createBattleSlicePresentation(position);const reduced=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches??false;
 const get=id=>host.querySelector('#'+id);const reset=()=>{host.innerHTML=renderSliceShell(model);position=slicePositions(model.encounter);presentation=createBattleSlicePresentation(position);lastStep=0;};reset();
 const enqueue=(events,at)=>presentation.enqueue(events,at);
 const hud=()=>{const s=model.state,e=model.encounter,max=E.stats(s).hp,enemyModels=normalizeBattleEnemies(e),units=[{id:'hero',name:s.hero,hp:e.heroHp,max},...e.enemies];get('sliceUnits').innerHTML=units.map(u=>{const p=position[u.id];return `<div class="sliceUnit ${u.id==='hero'?'hero':'enemy'} ${e.targetId===u.id?'selected':''} ${u.hp<=0?'dead':''}" style="--x:${p.x/480*100}%"><div class="sliceUnitHud"><b>${esc(u.name)}</b><div class="sliceHp"><i style="width:${Math.max(0,u.hp)/u.max*100}%"></i></div><small>${Math.ceil(Math.max(0,u.hp))}/${Math.ceil(u.max)}</small>${u.id!=='hero'?`<div class="sliceEffectStrip">${[...new Set(readEnemyEffectRows(e,u.id).map(r=>r.label+(r.layers?' '+r.layers:'')))].join(' · ')}</div>${enemyModels.find(m=>m.id===u.id)?.preparing?`<div class="sliceCastStrip">${esc(enemyModels.find(m=>m.id===u.id).preparing.name)}</div>`:''}`:''}${u.id==='hero'&&e.playerShieldLayers?.layers.some(l=>l.remaining>0)?`<div class="sliceShield">盾 ${Math.ceil(e.playerShieldLayers.layers.reduce((n,l)=>n+l.remaining,0))}</div>`:''}</div>${u.id!=='hero'?`<button class="sliceTarget" aria-label="选中${esc(u.name)}" data-slice-target="${esc(u.id)}" ${u.hp<=0?'disabled':''}></button>`:''}</div>`;}).join('');get('sliceRunLabel').textContent=s.running?'暂停':e.done?'已结束':'开始';get('sliceStatus').textContent=e.done?(e.win?'战斗胜利':'已撤退'):s.running?'交锋中':'已暂停';get('sliceSkills').innerHTML=skillButtons(s,e);get('slicePotionCount').textContent='药剂 '+(s.potionStacks?.['healing|0']??0);get('sliceOutcome').textContent=model.emissionError?'展示事件异常：'+model.emissionError:e.done?'本场结束 · 重开使用新的隔离角色':'点击敌人切换目标';get('sliceLog').innerHTML=model.logs.map(l=>'<p>'+esc(l)+'</p>').join('');};

 function frame(t){if(disposed)return;const now=Date.now();if(now-lastStep>=1100){lastStep=now;enqueue(model.advance(now),t);hud();}presentation.advance(t);drawBattleSliceCanvas(get('sliceCanvas'),{manifest,images,encounter:model.encounter,positions:position,animations:presentation.animations,time:t,reduced,floats:presentation.floats});raf=requestAnimationFrame(frame);}
 const listener=ev=>{const b=ev.target.closest('button');if(!b||!host.contains(b))return;if(b.dataset.sliceTarget){model.select(b.dataset.sliceTarget);hud();return;}if(b.dataset.sliceSkill){const d=SKILL_TREE_DESCRIPTIONS[b.dataset.sliceSkill];get('sliceHelp').hidden=false;get('sliceHelp').innerHTML=`<b>${esc(names[b.dataset.sliceSkill])}</b><p>${esc(d?.base||'')}</p>`;return;}const action=b.dataset.sliceAction;if(action==='record'){if(recorder?.state==='recording'){recorder.stop();return;}const canvas=get('sliceCanvas');if(!canvas.captureStream||typeof MediaRecorder==='undefined'){get('sliceOutcome').textContent='此浏览器不支持场景录制';return;}const chunks=[];recorder=new MediaRecorder(canvas.captureStream(30));recorder.ondataavailable=ev=>{if(ev.data.size)chunks.push(ev.data);};recorder.onstop=()=>{const url=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType||'video/webm'})),link=document.createElement('a');link.href=url;link.download='灰冠-战斗场景试作.webm';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);b.querySelector('span').textContent='录制场景';};recorder.start();b.querySelector('span').textContent='停止录制';return;}if(action==='toggle')model.toggle(Date.now());if(action==='potion')enqueue(model.drink(Date.now()).events,performance.now());if(action==='restart'){if(recorder?.state==='recording')recorder.stop();model.dispose();model=createBattleSliceModel({scenario});reset();}if(action==='log')get('sliceLog').hidden=!get('sliceLog').hidden;hud();};host.addEventListener('click',listener);hud();raf=requestAnimationFrame(frame);return {get model(){return model;},dispose(){disposed=true;if(recorder?.state==='recording')recorder.stop();cancelAnimationFrame(raf);model.dispose();host.removeEventListener('click',listener);}};
}
if(typeof document!=='undefined'&&document.getElementById('battleSlice'))mountBattleSlice(document.getElementById('battleSlice'),{scenario:new URLSearchParams(location.search).get('scenario')==='poison'?'poison':'fire'}).catch(error=>{document.getElementById('battleSlice').textContent='战斗试作尚未就绪：'+error.message;});
